	for i := range dst {
		dst[i] = 0
	}
	for j := range ls {
		v := uint32(ls[j]&63) | uint32(lm[j]&63)<<6
		b := 12 * j
		for i := 0; i < 12; i++ {
			if v>>uint(i)&1 != 0 {
				dst[(b+i)/8] |= 1 << uint((b+i)%8)
