				if sc != ls[j] || mn != lm[j] {
					t.Fatalf("sub %d group %d: wrote (%d, %d), read (%d, %d)",
						sub, j, ls[j], lm[j], sc, mn)
				}
			}
		}
		// Every bit the packing does not use has to stay zero, or the
		// padding byte would be carrying state the shader does not read.
		for j := range ls {
			ls[j], lm[j] = 63, 63
		}
