22	// TestBankQKIsTheSim is the stage's first gate, and it is an equality.
23	//
24	// L8c-3's number is a perplexity measured through `sim.go`, which round-trips
25	// a weight to floats and lets the fp16 kernels multiply them. This bank is
26	// the same format *stored*, so every value a kernel reads out of it has to be
27	// the value the simulation staged — not close to it. Both go through
28	// `asymEnc`, so the test is really that the packing and the addressing are
29	// each other's inverse, which is exactly the thing a tolerance would hide.
30	func TestBankQKIsTheSim(t *testing.T) {
31		rng := rand.New(rand.NewSource(7))
32		for _, tc := range []struct {
33			name    string
34			n, k    int
35			spec    string
36			mode    string
37			bits    float64
38			weights bool
39		}{
40			{"q4_k rtn 64x2560", 64, 2560, "q4_k/32", "rtn", 4.5, false},
41			{"q4_k imatrix 64x2560", 64, 2560, "q4_k/32", "imatrix", 4.5, true},
42			{"q4_k rtn 32x6144", 32, 6144, "q4_k/32", "rtn", 4.5, false},
43			{"q4_k search 32x256", 32, 256, "q4_k/32", "search", 4.5, false},
44			// L8c-6's family: 320 is ten groups of 32 and one super-block for
45			// the whole row, so the record is `packScaleMin12`'s twenty bytes
46			// and not ggml's sixteen. Both arms, because the calibrated one is
47			// the arm a bank is built at.
48			{"q4_k rtn 64x320", 64, 320, "q4_k/32", "rtn", 4.5, false},
49			{"q4_k imatrix 64x320", 64, 320, "q4_k/32", "imatrix", 4.5, true},
50			// **P3a's fifth bit**, the same rows again. The record does not move
51			// — ggml's Q5_K carries Q4_K's — so what this exercises that the
52			// four-bit rows do not is the `qh` plane's addressing: one bit a
53			// weight at bit (k%8) of the byte whose index is the *nibble word's*
54			// index inside its tile, which is the one place the two widths差.
55			{"q5_k rtn 64x2560", 64, 2560, "q5_k/32", "rtn", 5.5, false},
56			{"q5_k imatrix 64x2560", 64, 2560, "q5_k/32", "imatrix", 5.5, true},
57			{"q5_k rtn 32x6144", 32, 6144, "q5_k/32", "rtn", 5.5, false},
58			{"q5_k search 32x256", 32, 256, "q5_k/32", "search", 5.5, false},
59			{"q5_k rtn 64x320", 64, 320, "q5_k/32", "rtn", 5.5, false},
60			{"q5_k imatrix 64x320", 64, 320, "q5_k/32", "imatrix", 5.5, true},
61		} {
62			t.Run(tc.name, func(t *testing.T) {
63				q := mustQ4K(t, tc.spec, tc.mode)
64				x := make([]float32, tc.n*tc.k)
65				for i := range x {
66					x[i] = float32(rng.NormFloat64()) * 0.05
67				}
68				var qw []float32
69				if tc.weights {
70					qw = make([]float32, tc.k)
71					for i := range qw {
72						qw[i] = float32(rng.Float64()) + 1e-3
73					}
74				}
75				// The simulation's answer: the floats a kernel would multiply.
76				want := append([]float32(nil), x...)
77				if err := q.ApplyWeighted(want, tc.k, qw); err != nil {
78					t.Fatal(err)
79				}
80				// The bank's: the same format, stored and read back.
81				bits, err := qkBits(q)
82				if err != nil {
83					t.Fatal(err)
84				}
85				st := newQKStage(bits, tc.n, tc.k)
86				// A row remapping, so the addressing is exercised rather than
87				// assumed to be the identity.
88				perm := make([]int, tc.n)
89				for i := range perm {
90					perm[i] = tc.n - coopMatTile - (i/coopMatTile)*coopMatTile + i%coopMatTile
91				}
92				if err := st.Fill(x, tc.n, tc.k, func(i int) int { return perm[i] }, q, qw); err != nil {
93					t.Fatal(err)
94				}
95				if got := qkBytes(bits, tc.n, tc.k); got != st.Len() {
96					t.Fatalf("qkBytes says %d, the planes are %d", got, st.Len())
97				}
98				// 4.500 bits at both super-block lengths: eight groups carry
99				// 4 + 12 = 16 bytes over 256 weights, ten carry 4 + 15 = 19
100				// rounded up to a word over 320. The fifth bit is one more.
101				if bpw := float64(st.Len()) * 8 / float64(tc.n*tc.k); bpw != tc.bits {
102					t.Fatalf("%.4f bits a weight, want %.1f", bpw, tc.bits)
103				}
104				diff := 0
105				for i := 0; i < tc.n; i++ {
106					for c := 0; c < tc.k; c++ {
107						got := qkDequant(st.Lvl, st.High, st.Rec, bits, tc.n, tc.k, perm[i], c)
108						if got != want[i*tc.k+c] {
109							diff++
110						}
111					}
112				}
113				if diff != 0 {
114					t.Fatalf("%d of %d values differ from the simulation", diff, tc.n*tc.k)
115				}
116			})
117		}
