120	// TestQ4KRecordPackings is the two packings against each other's inverse,
121	// value for value over every representable six-bit pair: LLM.md L8c-6.
122	//
123	// It exists because the ten-group one is **ours** rather than ggml's — there
124	// is no oracle for it the way `reference/quant_ref.c` is the oracle for the
125	// levels — so the only thing that can be checked is that the writer and the
126	// two readers (here and in shaders/llm_q4k.glsl, which is the same
127	// arithmetic) agree. A packing that lost a bit would show up as a wrong
128	// scale on one group in sixty-four, which is exactly the sort of error a
129	// perplexity run reports as "the format costs a bit more than expected".
130	func TestQ4KRecordPackings(t *testing.T) {
131		rng := rand.New(rand.NewSource(11))
132		for _, sub := range []int{8, 10} {
133			ls, lm := make([]int, sub), make([]int, sub)
134			rec := make([]byte, q4kRecordBytes(sub))
135			for trial := 0; trial < 2000; trial++ {
136				for j := 0; j < sub; j++ {
137					ls[j], lm[j] = rng.Intn(64), rng.Intn(64)
138				}
139				for i := range rec {
140					rec[i] = 0
141				}
142				switch sub {
143				case 8:
144					packScaleMinK4(rec[4:16], ls, lm)
145				default:
146					packScaleMin12(rec[4:19], ls, lm)
147				}
148				for j := 0; j < sub; j++ {
149					_, _, sc, mn := unpackQ4KRecord(rec, sub, j)
150					if sc != ls[j] || mn != lm[j] {
151						t.Fatalf("sub %d group %d: wrote (%d, %d), read (%d, %d)",
152							sub, j, ls[j], lm[j], sc, mn)
153					}
154				}
155			}
156			// Every bit the packing does not use has to stay zero, or the
157			// padding byte would be carrying state the shader does not read.
158			for j := range ls {
159				ls[j], lm[j] = 63, 63
160			}
161			for i := range rec {
162				rec[i] = 0
163			}
164			if sub == 10 {
165				// Ten twelve-bit pairs are 120 bits, which is bytes 4..18 to the
166				// last bit; byte 19 is the word alignment and nothing else.
167				packScaleMin12(rec[4:19], ls, lm)
168				if rec[19] != 0 {
169					t.Fatalf("the ten-group record's twentieth byte is %02x, want the pad", rec[19])
170				}
171				for i := 4; i < 19; i++ {
172					if rec[i] != 0xFF {
173						t.Fatalf("all-63 pairs left byte %d at %02x, want ff", i, rec[i])
174					}
175				}
176			}
177		}
178	}

