		if len(a) != len(b) {
			t.Fatalf("%s: %d values against %d", what, len(a), len(b))
		}
		for i := range a {
			if a[i] != b[i] {
				t.Fatalf("%s[%d]: bank %.9g, simulation %.9g", what, i, a[i], b[i])
